        <!-- TRANSFER NOTE DETAILS -->
<div class="row mt-4" v-if="selectedTransferNote">

  <!-- Transfer Note Details -->
  <div class="col-md-6">
    <h4 class="text-center">TRANSFER NOTE DETAILS</h4>

    <table class="table table-bordered shadow">
