    </table>
  </div>


  <!-- TRANSFER NOTE CHECKPOINTS -->
  <div class="col-md-6">
    <h4 class="text-center">TRANSFER NOTE CHECKPOINTS</h4>

    <table class="table table-bordered shadow">
      <tbody>

        <tr v-for="checkpoint in selectedTransferNote?.checkpoints" :key="checkpoint.id">
          <td><strong>{{ jobcard?.machine?.fuel_type?.toUpperCase()}} MEASURED :</strong></td>
          <td>{{ checkpoint.fuel || '0' }} LTs</td>
        </tr>

                <tr v-for="checkpoint in selectedTransferNote?.checkpoints" :key="checkpoint.id">
          <td><strong>DRIVER :</strong></td>
          <td>{{ checkpoint?.driver?.toUpperCase() || 'NO DRIVER' }}</td>
