        <tr v-for="checkpoint in selectedTransferNote?.checkpoints" :key="'oil'+checkpoint.id">
          <td><strong>ENGINE OIL</strong></td>
          <td>
            <span v-if="checkpoint.engine_oil === 1" class="badge bg-success">
