      </tbody>
    </table>

  </div>

</div>

        <!-- SPARES USED -->
        <div class="row mt-4" v-if="items.length > 0">
          <div class="col-md-12">
            <h4 class="text-center">SPARES USED</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="items" :columns="itemColumns" :options="table_option">
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                   
                        </v-client-table>                        
                    </div>
                </div>
            </div>
          </div>
        </div>

        <!-- TYRES -->
        <div class="row mt-4">
          <div class="col-md-6" v-if="tyres.length > 0">
            <h4 class="text-center">TYRES USED</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="tyres" :columns="tyreColumns" :options="table_option" />
                    </div>
                </div>
                </div>
          </div>

          <!-- OUTSIDE MAINTENANCE -->
          <div class="col-md-6" v-if="outsideMaintenance.length > 0">
            <h4 class="text-center">OUTSIDE MAINTENANCE</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="outsideMaintenance" :columns="outsideMaintenanceColumns" :options="table_option">
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
          </div>
        </div>

        <!-- LABOUR COST -->
        <div class="row mt-4" >
          <div class="col-md-6" v-if="labourCost.length > 0">
            <h4 class="text-center">LABOUR COST</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="labourCost" :columns="costNoteColumns" :options="table_option" >
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
          </div>
        </div>

        <!-- BODY WORKS -->
        <div class="row mt-4" v-if="bodyWorks.length > 0">
          <div class="col-md-12">
            <h4 class="text-center">BODY WORKS </h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="bodyWorks" :columns="itemColumns" :options="table_option">
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                   
                        </v-client-table>                        
                    </div>
                </div>
            </div>
          </div>
        </div>

           <!-- ELECTRICAL WORKS -->
        <div class="row mt-4">
            <div class="col-md-6" v-if="electricalWorks.length > 0">
            <h4 class="text-center">ELECTRICAL WORKS</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="electricalWorks" :columns="costNoteColumns" :options="table_option" >
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
          </div>
          
<!-- ENGINEERING WORKS -->
         <div class="col-md-6" v-if="engineeringWorks.length > 0">
            <h4 class="text-center">ENGINEERING WORKS</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="engineeringWorks" :columns="costNoteColumns" :options="table_option" >
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
          </div>
        </div>
          <!-- ADDITIONAL WORKS -->
        <div class="row mt-4" >
            <div class="col-md-6" v-if="additionalWorks.length > 0">
            <h4 class="text-center">ADDITIONAL WORKS (Others)</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div class="custom-table shadow">
                        <v-client-table :data="additionalWorks" :columns="costNoteColumns" :options="table_option" >
                            <template #status="props">
                               <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
          </div>
          
<!-- COST SUMMARY -->
          <div class="col-md-6" v-if="costNote?.total > 0">
            <h4 class="text-center">COST SUMMARY</h4>
            <ul class="list-group shadow">
              <li class="list-group-item">Spares : {{ costNote?.spares?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Tyres : {{ costNote?.tyres?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Body Works : {{ costNote?.body_works?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Electrical Works : {{ costNote?.electrical_works?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Labour : {{ costNote?.labour?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Engineering : {{ costNote?.engineering?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item">Additional : {{ costNote?.additional?.toLocaleString() || 0 }}/=</li>
              <li class="list-group-item fw-bold">Total : {{ costNote?.total?.toLocaleString() || 0 }}/=</li>
            </ul>
          </div>
        </div>

      </div>

      <!-- FOOTER -->
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" id ="close_transfer_note">Close</button>
      </div>
    </div>
  </div>
</div>
    </div>
</template>



<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import ApprovalBlock from '@/components/reusables/ApprovalBlock.vue';
    import { useRouter } from 'vue-router';
    const router = useRouter();
    
    useMeta({ title: 'Jobcard Transfer Notes' });  
    
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const formatNumber = inject('formatNumber');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    const status = ref('');
    const remark = ref('');
    const loading_spinner = ref(false);
    const columns = ref(['SNo','date','card','name','service_type','destination','issuer','remark','status','actions']);    
    const name = ref('');
    const quantity = ref('');
    const units = ref('');
    const items = ref([]);
    const bodyWorks = ref([]);
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

   const transfer_notes = ref([])
    const getJobcardTransferNote = async () => {
        loading_spinner.value = true;
        try {
            const response = await axiosInstance.get('jobcard-transfer-notes');
            transfer_notes.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                id: item.id,
                card: item.jobcard_id,
                jobcard : item.jobcard,
                destination : item.destination.name,
                issuer : item.issuer.name,
                asset_id : item.jobcard.machine_id,
                name : item.jobcard.machine.name + ' - ' + item.jobcard.machine.type_name,  
                remark : item.remark,  
                service_type : item.jobcard.service_type,                  
                status: item.status,          
                date:formatDate(item.date)                
            }));
        } catch (error) {
            showError(error.message);
            console.log (error)
        }finally{
            loading_spinner.value = false;
        }
    };
   

const getStatusClass = (status) => {
    if (!status) return 'badge-secondary';
    
    const statusUpper = status.toUpperCase();
    
    switch(statusUpper) {
        case 'APPROVED':
            return 'badge-success';
        case 'REJECTED':
            return 'badge-danger';
        case 'REMARKED':
            return 'badge-info';
        case 'ON HOLD':
            return 'badge-warning';
        case 'RECEIVED':
            return 'badge-primary';
        default:
            return 'badge-secondary';
    }
};

  
const itemColumns = ref(['SNo', 'spare', 'unit', 'required', 'available', 'purchasable', 'rate', 'cost', 'purchase_cost', 'remark', 'description', 'status']);
const tyreColumns = ref(["SNo", "tyre_no", "rate", "date_changed"]);
const outsideMaintenanceColumns = ref(["SNo", "item", "description", "quantity","vendor", "status"]);
const costNoteColumns = ref(['SNo', 'description', 'beneficiary', 'qty', 'rate', 'cost', 'status']);


const selectedTransferNote = ref(null);
const jobcard = ref(null);
const defects = ref([]);
const work_carried_out = ref([]);
const tyres = ref([]);
const outsideMaintenance = ref([]);
const labourCost = ref([]);
const electricalWorks = ref([]);
const engineeringWorks = ref([]);
const additionalWorks = ref([]);
const costNote = ref({});


const OpenTransferNoteModal = (row) => {
    console.log(row)
    selectedTransferNote.value = row;
    jobcard.value = { ...row.jobcard };

    const maintainanceLogs = row.jobcard?.maintainance_logs || [];
    defects.value = maintainanceLogs.filter(log => log.issue_type === 'defect');
    work_carried_out.value = maintainanceLogs.filter(log => log.issue_type === 'work_done');

    const itemUsages = row.jobcard?.item_usages || [];

    const formatItemUsage = (itemsArray) => itemsArray.map((item, index) => ({
        SNo: index + 1,
        id: item.id,
        spare: item.item_name,
        item_name: item.item_name || '--',
        unit: item.unit ?? 'nill',
        required: item.quantity,
        available: Math.max(item.store_quantity, 0),
        purchasable: item.store_quantity - item.quantity < 0 
            ? Math.abs(item.store_quantity - item.quantity) 
            : 0,
        purchase_cost: formatNumber(
            (item.store_quantity - item.quantity < 0 
                ? Math.abs(item.store_quantity - item.quantity) 
                : 0) * item.rate
        ),
        rate: Number(item.rate).toLocaleString() + '/=',
        rate_original: item.rate,
        cost: (item.quantity * item.rate).toLocaleString() + '/=',
        status: item.status,
        remark: item.remark,
        description: item.description,
        date: item.date,
    }));

    items.value = formatItemUsage(itemUsages.filter(i => i.usage_type === 'spares'));
    bodyWorks.value = formatItemUsage(itemUsages.filter(i => i.usage_type === 'body_works'));
    tyres.value = itemUsages
        .filter(i => i.usage_type === 'tyres')
        .map((item, index) => ({
            SNo: index + 1,
            id: item.id,
            tyre_no: item.description,
            date_changed: item.date,
            quantity: item.quantity,
            rate: Number(item.rate).toLocaleString() + '/=',
            cost: (item.quantity * item.rate).toLocaleString() + '/=',
            status: item.status,
        }));

    const costNotes = row.jobcard?.cost_notes || [];
    const formatCostNote = (notesArray) => notesArray.map((item, index) => ({
        ...item,
        SNo: index + 1,
        qty: item.quantity,
        rate: Number(item.rate).toLocaleString() + '/=',
        rate_original: item.rate,
        cost: (item.quantity * item.rate).toLocaleString() + '/=',
        status: item.status,
    }));

    labourCost.value = formatCostNote(costNotes.filter(n => n.costnote_type === 'labour'));
    electricalWorks.value = formatCostNote(costNotes.filter(n => n.costnote_type === 'electric'));
    engineeringWorks.value = formatCostNote(costNotes.filter(n => n.costnote_type === 'engineering'));
    additionalWorks.value = formatCostNote(costNotes.filter(n => n.costnote_type === 'additional'));
    

    outsideMaintenance.value = (row.jobcard?.outside_maintenances || []).map((item, index) => ({
        ...item,
        SNo: index + 1,
        vendor: item.vendor?.name || '--',
    }));
    
    costNote.value = row.jobcard?.cost_summary || {};
};


const updatingStatus = ref(false);
const approveJobcardTransferNote = async (status) => {
    updatingStatus.value = true;
    
    const statusNames = {
        3: 'APPROVED',
        4: 'REJECTED',
        14: 'REMARKED',
        17: 'ON HOLD'
    };
    
    try {
        const payload = {
            status: statusNames[status],
            remark: remark.value,
            remarker_id: JSON.parse(localStorage.getItem("user")).id
        };
        await axiosInstance.put(`/jobcard-transfer-notes/${selectedTransferNote.value.id}`, payload);
        showMessage("submitted successfully!");
        remark.value = '';
        document.getElementById('close_transfer_note').click()
        getJobcardTransferNote();
    } catch (error) {
        showError(error.message);
        console.log(error);
    } finally {
        updatingStatus.value = false;
    }
};

    onMounted(() => {
        getJobcardTransferNote();
    });
</script>